"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["71658"],{16946(e){e.exports=JSON.parse('{"id":"FIN-1264","slug":"managed-float","term":"Managed Float","also_known_as":[],"difficulty":"Advanced","definition":"A managed float is an exchange rate system in which a currency\'s value is mainly set by market supply and demand, but the central bank intervenes from time to time to influence its value or reduce volatility.","explanation":["A managed float, sometimes called a dirty float, sits between a fully floating exchange rate and a fixed one. The central bank does not commit to a specific rate, but it may buy or sell its own currency, adjust interest rates or use other tools to prevent sharp or disorderly movements.","For example, if a currency falls rapidly because of market panic, the central bank might sell some of its foreign currency reserves to buy its own currency, slowing the decline.","Many emerging market countries use managed floats, including India and Singapore, which manages its currency against a basket of currencies. This approach gives some of the flexibility of a floating rate while reducing the risks of extreme volatility, which can hurt trade, inflation and financial stability.","Managed floats can be less transparent than fully floating or fixed systems, since markets may be uncertain about when the central bank will intervene. Intervention also requires adequate foreign reserves."],"note":"","total":1725,"prev":{"slug":"maintenance-margin","term":"Maintenance Margin"},"next":{"slug":"management-accounts","term":"Management Accounts"}}')}}]);